function createCategories(){


    let cats=[
        "All",
        ...new Set(
            games.map(g=>g.category)
        )
    ];



    cats.forEach((cat,index)=>{


        let y=
        260+(index*55);



        let button =
        document.createElementNS(
        "http://www.w3.org/2000/svg",
        "g"
        );



        button.innerHTML=`

        <rect
        x="60"
        y="${y-30}"
        width="170"
        height="40"
        rx="20"
        fill="#ffffff15"/>


        <text
        x="145"
        y="${y}"
        text-anchor="middle"
        fill="white"
        font-size="16"
        font-family="Arial">
        ${cat}
        </text>

        `;



        button.onclick=()=>{


            if(cat==="All")
                displayGames(games);

            else

                displayGames(
                    games.filter(
                    g=>g.category===cat
                    )
                );


        };



        categoryLayer.appendChild(button);


    });


}





function displayGames(list){

    gamesLayer.replaceChildren();


    list.forEach((game,index)=>{


        const ns =
        "http://www.w3.org/2000/svg";


        let group =
        document.createElementNS(ns,"g");


        let x =
        330 + ((index % 3) * 260);


        let y =
        260 + (Math.floor(index / 3) * 260);



        let rect =
        document.createElementNS(ns,"rect");

        rect.setAttribute("x",x);
        rect.setAttribute("y",y);
        rect.setAttribute("width","230");
        rect.setAttribute("height","220");
        rect.setAttribute("rx","25");
        rect.setAttribute("fill","#222");

        group.appendChild(rect);



        let title =
        document.createElementNS(ns,"text");

        title.setAttribute("x",x+115);
        title.setAttribute("y",y+40);
        title.setAttribute("fill","white");
        title.setAttribute("font-size","20");
        title.setAttribute("text-anchor","middle");
        title.textContent=game.name;


        group.appendChild(title);



        let category =
        document.createElementNS(ns,"text");


        category.setAttribute("x",x+115);
        category.setAttribute("y",y+75);
        category.setAttribute("fill","#aaa");
        category.setAttribute("font-size","14");
        category.setAttribute("text-anchor","middle");

        category.textContent=
        game.category;


        group.appendChild(category);



        let play =
        document.createElementNS(ns,"text");


        play.setAttribute("x",x+115);
        play.setAttribute("y",y+150);
        play.setAttribute("fill","white");
        play.setAttribute("font-size","18");
        play.setAttribute("text-anchor","middle");


        play.textContent="PLAY";


        group.appendChild(play);



        group.onclick=()=>{

            window.open(
                game.url,
                "_blank"
            );

        };


        gamesLayer.appendChild(group);


    });


}
